// Selector grammar (omp's parseSqliteSelector)
// ---------------------------------------------------------------------------

/// The parsed SQLite target selector (omp's SqliteSelector).
sealed class SqliteSelector {
  const SqliteSelector();
}

/// `db.sqlite` — list non-`sqlite_%` tables with row counts.
