        final library = CBuilder.library(
          name: 'sqlite3',
          packageName: 'sqlite3',
          assetName: name,
          sources: sourceFiles,
          includes: {
            for (final source in sourceFiles) p.dirname(source),
            ...additionalIncludes,
          }.toList(),
          defines: defines,
          flags: [
            if (input.config.code.targetOS == OS.linux) ...[
