enum LibraryType {
  /// SQLite build, with sources taken from https://sqlite.org/download.html.
  sqlite3,

  /// SQLite multiple ciphers build, with sources taken from
  /// https://github.com/utelle/SQLite3MultipleCiphers.
  sqlite3mc,

