  if (Platform.isMacOS) {
    final zipAsset = _zipAssetName();
    if (zipAsset != null) {
      _say('archive not found — trying $zipAsset…');
      return fallbackZipUpdate(
        client,
        tag,
        zipAsset,
        target,
        latest,
        runProcess,
      );
    }
  }
  _warn('download failed (HTTP ${streamed.statusCode}): $url');
  return 1;
}

