548:        final install = File('install_local.sh').readAsStringSync();
554:              'install_local.sh must not read the version from pubspec.yaml — '
Future<int> runSelfUpdate({
  required String currentVersion,
  Install Function() detectInstall = _detectInstall,
  http.Client Function() newClient = http.Client.new,
  Future<ProcessResult> Function(String, List<String>) runProcess = Process.run,
  String pem = kFaReleaseSigningPem,
}) async {
  final install = detectInstall();
  if (install.kind == InstallKind.devRun) {
    _warn('fa update works for installed binaries, not source runs.');
    return 1;
  }

  final client = newClient();
  try {
    _say('current version: $currentVersion');
    final tag = await fetchLatestTag(client: client);
    if (tag == null) {
      _warn('cannot reach GitHub Releases (network or rate limit)');
      return 1;
    }
    final latest = tag.replaceFirst('v', '');
    _say('latest release:  $latest');
    if (compareVersions(latest, currentVersion) <= 0) {
      _say('already up to date.');
      return 0;
    }

    if (install.kind == InstallKind.pubGlobal) {
      return (await _pubGlobalUpdate(
        currentVersion: currentVersion,
        latest: latest,
        runProcess: runProcess,
      )).$1;
    }

    return await _binaryUpdate(client, install, tag, latest, runProcess, pem);
  } finally {
    client.close();
  }
}

/// Pub-global update path: re-activate the package, forcing a clean
/// re-activation first when pub believes a NEWER spec than the running
/// binary.
Future<(int, String?)> _pubGlobalUpdate({
  required String currentVersion,
  required String latest,
  required Future<ProcessResult> Function(String, List<String>) runProcess,
}) async {
  _say('updating via dart pub global activate…');
  // A stale or half-written snapshot: pub believes a NEWER spec than the
  // running binary, so a plain activate no-ops (or chokes decoding the
  // old snapshot). Force a clean re-activation then.
  final listed = await runProcess('dart', ['pub', 'global', 'list']);
  final activeVersion = RegExp(
    r'flutter_agent_harness\s+(\d+\.\d+\.\d+)',
  ).firstMatch('${listed.stdout}${listed.stderr}')?.group(1);
  if (activeVersion != null &&
      compareVersions(activeVersion, currentVersion) > 0) {
    _say(
      'rebuilding the activated snapshot '
      '(spec $activeVersion, running $currentVersion)…',
    );
    final deactivate = await runProcess('dart', [
      'pub',
      'global',
      'deactivate',
      'flutter_agent_harness',
    ]);
    stdout.write(deactivate.stdout);
    stderr.write(deactivate.stderr);
  }
  final result = await runProcess('dart', [
    'pub',
    'global',
    'activate',
    'flutter_agent_harness',
  ]);
  stdout.write(result.stdout);
  stderr.write(result.stderr);
  if (result.exitCode == 0 &&
      compareVersions(latest, activeVersion ?? currentVersion) > 0) {
    _say(
      'note: pub.dev lags behind GitHub ($latest available as a binary) — '
      'curl -fsSL https://fa1.dev/install.sh | sh',
    );
  }
  final activated = RegExp(
    r'[Aa]ctivated flutter_agent_harness (\d+\.\d+\.\d+)',
  ).firstMatch('${result.stdout}${result.stderr}')?.group(1);
  return (result.exitCode, activated);
}

/// Binary update path: download the release archive for this platform,
/// verify its provenance, and swap in the new binary + dylibs. Falls back
/// to the macOS `.zip` asset when the archive is missing from the release.
Future<int> _binaryUpdate(
  http.Client client,
  Install install,
  String tag,
  String latest,
  Future<ProcessResult> Function(String, List<String>) runProcess,
  String pem,
) async {
  final archive = _archiveName();
  if (archive == null) {
    _warn('no prebuilt archive for this platform — install via Dart instead');
    return 1;
  }
  final target = install.executable;
  final installDir = File(target).parent;
  final url = 'https://github.com/$_repo/releases/download/$tag/$archive';
  _say('downloading $archive…');
  final request = http.Request('GET', Uri.parse(url));
  final http.StreamedResponse streamed;
  try {
    streamed = await client.send(request).timeout(kFaUpdateNetworkTimeout);
  } on Exception catch (error) {
    _warn('download failed (network): $error');
    return 1;
  }
  if (streamed.statusCode == 200) {
    final List<int> bytes;
    try {
      bytes = await streamed.stream.toBytes().timeout(kFaUpdateArchiveTimeout);
    } on Exception catch (error) {
      _warn('download failed (network): $error');
      return 1;
    }
    if (!await verifyReleaseProvenance(
      client: client,
      tag: tag,
      archiveName: archive,
      archiveBytes: bytes,
      pem: pem,
    )) {
      _warn('update aborted: release provenance check failed for $archive');
      return 1;
    }
    return _extractAndSwap(
      bytes,
      archive,
      target,
      installDir,
      latest,
      runProcess,
    );
  }
  // Fallback: macOS release may only have the versioned .zip (the sandboxed
  // app bundle). Try the stable zip name and extract the binary from the app bundle.
  if (Platform.isMacOS) {
    final zipAsset = _zipAssetName();
    if (zipAsset != null) {
      _say('archive not found — trying $zipAsset…');
      return fallbackZipUpdate(
        client,
        tag,
        zipAsset,
        target,
        latest,
        runProcess,
      );
    }
  }
  _warn('download failed (HTTP ${streamed.statusCode}): $url');
  return 1;
}

/// The stable zip asset name for macOS (uploaded by build-macos.yml).
String? _zipAssetName() {
  final abi = Abi.current().toString();
  return switch (abi) {
    'macos_arm64' => 'fa-macos-arm64-mac.zip',

Future<int> runSelfUninstall({
  Install Function() detectInstall = _detectInstall,
  Future<bool> Function(String) confirm = _confirm,
  Future<ProcessResult> Function(String, List<String>) runProcess = Process.run,
  Map<String, String>? environment,
}) async {
  final install = detectInstall();
  if (install.kind == InstallKind.devRun) {
    _warn('fa uninstall works for installed binaries, not source runs.');
    return 1;
  }

  if (!await confirm('Uninstall fa (binary + PATH entry)?')) {
    _say('aborted.');
    return 1;
  }

  if (install.kind == InstallKind.pubGlobal) {
    await _pubGlobalDeactivate(runProcess);
  } else {
    _removeBinaryInstall(install);
  }

  await _maybeRemoveDataDir(confirm, environment);
  _say('fa uninstalled.');
  return 0;
}

/// Pub-global uninstall path: deactivate the activated package.
Future<void> _pubGlobalDeactivate(
  Future<ProcessResult> Function(String, List<String>) runProcess,
) async {
  _say('deactivating via dart pub global…');
  final result = await runProcess('dart', [
    'pub',
    'global',
    'deactivate',
    'flutter_agent_harness',
  ]);
  stdout.write(result.stdout);
  stderr.write(result.stderr);
}

/// Binary uninstall path: the Windows user-PATH entry, the executable,
/// and — on Windows — the whole `%LOCALAPPDATA%\Fa` directory.
void _removeBinaryInstall(Install install) {
  final exe = File(install.executable);
  final windowsRoot = _windowsInstallRoot(install);
  if (Platform.isWindows) {
    _removeFromUserPath(File(install.executable).parent.path);
  }
  if (exe.existsSync()) exe.deleteSync();
  if (windowsRoot != null && windowsRoot.existsSync()) {
    windowsRoot.deleteSync(recursive: true);
  }
  _say('removed ${install.executable}');
}

/// The install root to remove on Windows: the release layout is
/// `%LOCALAPPDATA%\Fa\bin\fa.exe`, so the whole Fa directory (the
/// executable's grandparent) is ours; null elsewhere, where just the
/// binary file is.
Directory? _windowsInstallRoot(Install install) {
  return Platform.isWindows ? File(install.executable).parent.parent : null;
}

/// Offers to delete the `~/.fah` data directory (a second confirmation);
/// kept silently when declined or absent.
Future<void> _maybeRemoveDataDir(
  Future<bool> Function(String) confirm,
  Map<String, String>? environment,
) async {
  final env = environment ?? Platform.environment;
  final home = env['HOME'] ?? env['USERPROFILE'];
  if (home != null && home.isNotEmpty) {
    final dataDir = Directory('$home/.fah');
    if (dataDir.existsSync() &&
        await confirm('Also delete $home/.fah (sessions, config, logs)?')) {
      dataDir.deleteSync(recursive: true);
      _say('removed ${dataDir.path}');
    } else if (dataDir.existsSync()) {
      _say('kept ${dataDir.path} (sessions and config preserved).');
    }
  }
}

/// Removes [binDir] from the Windows user PATH (registry), mirroring how
/// install.ps1 added it.
void _removeFromUserPath(String binDir) {
  final script =
      '\$p = [Environment]::GetEnvironmentVariable("Path", "User"); '
      '\$parts = \$p -split ";" | Where-Object { \$_ -and '
      '(\$_.TrimEnd("\\") -ne "$binDir".TrimEnd("\\")) }; '
      '[Environment]::SetEnvironmentVariable('
      '"Path", (\$parts -join ";"), "User")';
  try {
    Process.runSync('powershell', ['-NoProfile', '-Command', script]);
  } on ProcessException catch (error) {
    _warn('could not update the user PATH: $error');
  }
}

/// SQLite target reads for the `read` tool (omp's `#readSqlite`): candidate probing, read-only open, and the selector views (table list, schema+sample, single row, paged query, raw query). Split out of `builtin_tools.dart` to keep that file under the repo line gate; same library (a `part of`), so the privates stay visible.
part of 'builtin_tools.dart';

// ---------------------------------------------------------------------------
// read: SQLite targets (omp's #readSqlite)
// ---------------------------------------------------------------------------

/// Probes [rawPath] for SQLite targets (`data.db:table?…`) and renders the
/// selected view when a candidate names an existing database file. Returns
/// null when no candidate resolves. Without a [SqliteEngine] (web hosts have
/// no FFI) a resolved target yields a clean "not supported" note instead of
/// opening the file.
Future<ToolExecutionResult?> _tryReadSqlite(
  ExecutionEnv env,
  String rawPath,
  SqliteEngine? engine,
) async {
  final candidates = parseSqlitePathCandidates(rawPath);
  for (final candidate in candidates) {
    final info = await env.fileInfo(candidate.sqlitePath);
    if (info.isErr) continue;
    if (info.valueOrNull!.kind != FileKind.file) continue;
    return _readSqliteTarget(env, candidate, engine);
  }
  return null;
}

/// Opens the resolved SQLite [candidate] read-only and renders its selected
/// view (omp's `#readSqlite`). Without a [SqliteEngine] (web hosts have no
/// FFI) yields a clean "not supported" note instead of opening the file.
Future<ToolExecutionResult> _readSqliteTarget(
  ExecutionEnv env,
  SqlitePathCandidate candidate,
  SqliteEngine? engine,
) async {
  final selector = parseSqliteSelector(
    candidate.subPath,
    candidate.queryString,
  );
  if (engine == null) {
    return ToolExecutionResult.text(
      '[SQLite database reads are not supported in this environment '
      '(no SQLite engine available); ${candidate.sqlitePath} was not '
      'opened.]',
    );
  }

  final absolute =
      (await env.absolutePath(candidate.sqlitePath)).valueOrNull ??
      candidate.sqlitePath;
  SqliteDatabase? db;
  try {
    db = engine.openReadOnly(absolute);
    return _renderSqliteSelector(db, selector);
  } on StateError {
    rethrow;
  } on Object catch (error) {
    // Engine/backend failures (e.g. "file is not a database") surface as
    // the tool's error channel, mirroring omp's ToolError wrap.
    throw StateError('$error');
  } finally {
    db?.close();
  }
}

/// Renders one parsed SQLite selector against the open database (omp's
/// selector views: table list, schema+sample, single row, paged query, raw
/// query).
ToolExecutionResult _renderSqliteSelector(
  SqliteDatabase db,
  SqliteSelector selector,
) {
  switch (selector) {
    case SqliteListSelector():
      final tables = listSqliteTables(db)
          .take(maxSqliteTableListEntries)
          .toList();
      return ToolExecutionResult.text(renderSqliteTableList(tables));
    case SqliteSchemaSelector(:final table, :final sampleLimit):
      return _readSqliteSchema(db, table, sampleLimit);
    case SqliteRowSelector(:final table, :final key):
      return _readSqliteRow(db, table, key);
    case SqliteQuerySelector(
      :final table,
      :final limit,
      :final offset,
      :final order,
      :final where,
    ):
      return _readSqliteTablePage(
        db,
        table,
        limit: limit,
        offset: offset,
        order: order,
        where: where,
      );
    case SqliteRawSelector(:final sql):
      return _readSqliteRawQuery(db, sql);
  }
}

/// Renders a single row looked up by key (omp's row view), or the "no row"
/// note when the key matches nothing.
ToolExecutionResult _readSqliteRow(
  SqliteDatabase db,
  String table,
  String key,
) {
  final lookup = resolveSqliteRowLookup(db, table);
  final row = getSqliteRow(db, table, lookup, key);
  if (row == null) {
    return ToolExecutionResult.text(
      "No row found in table '$table' for key '$key'.",
    );
  }
  return ToolExecutionResult.text(renderSqliteRow(row));
}

/// Renders one page of a table query (omp's paged-query view).
ToolExecutionResult _readSqliteTablePage(
  SqliteDatabase db,
  String table, {
  required int limit,
  required int offset,
  required String? order,
  required String? where,
}) {
  final page = querySqliteRows(
    db,
    table,
    limit: limit,
    offset: offset,
    order: order,
    where: where,
  );
  return ToolExecutionResult.text(
    renderSqliteTable(
      page.columns,
      page.rows,
      totalCount: page.totalCount,
      offset: offset,
      limit: limit,
      table: table,
    ),
  );
}

/// Renders a raw `q=SELECT …` query result (omp's raw-query view), with the
/// row-cap notice when the engine truncated the result.
ToolExecutionResult _readSqliteRawQuery(SqliteDatabase db, String sql) {
  final result = executeSqliteReadQuery(db, sql);
  var output = renderSqliteTable(
    result.columns,
    result.rows,
    totalCount: result.rows.length,
    offset: 0,
    limit: result.rows.isEmpty ? defaultToolMaxLines : result.rows.length,
    table: 'query',
  );
  if (result.truncated) {
    output +=
        '\n[Output capped at $maxSqliteRawQueryRows rows; add a '
        'LIMIT/OFFSET clause to the query to page through more]';
  }
  return ToolExecutionResult.text(output);
}

/// Renders a table schema plus the first sample page (omp's schema view),
/// with a continuation hint when the table has more rows than the sample.
ToolExecutionResult _readSqliteSchema(
  SqliteDatabase db,
  String table,
  int sampleLimit,
) {
  final sample = querySqliteRows(db, table, limit: sampleLimit, offset: 0);
  var output = renderSqliteSchema(
    getSqliteTableSchema(db, table),
    SqliteRows(columns: sample.columns, rows: sample.rows),
  );
  if (sample.rows.length < sample.totalCount) {
    final remaining = sample.totalCount - sample.rows.length;
    output +=
        '\n[$remaining more rows; append '
        ':$table?limit=$defaultSqliteQueryLimit&offset=${sample.rows.length} '
        'to the database path to continue]';
  }
  return ToolExecutionResult.text(output);
}

