  String toString() {
    final buffer = StringBuffer('SqliteException(')
      ..write(extendedResultCode)
      ..write('): ')
      ..write(operation == null ? '' : 'while $operation, ')
      ..write(message);

    if (explanation != null) {
      buffer
        ..write(', ')
        ..write(explanation);
    }

    if (causingStatement != null) {

