Future<void> copyBundleLibs(Directory bundleDir, Directory installDir) async {
  final srcLib = Directory('${bundleDir.path}/lib');
  if (!srcLib.existsSync()) return;
  final libDir = Directory('${installDir.parent.path}/lib');
